1	package fleet
2	
3	import (
4		"errors"
5		"sort"
6		"sync"
7		"time"
8	)
9	
10	var (
11		ErrDeviceNotFound    = errors.New("device not found")
12		ErrBatchConflict     = errors.New("batch conflicts with stored events")
13		ErrRuleNotFound      = errors.New("rule not found")
14		ErrAlertNotFound     = errors.New("alert not found")
15		ErrRuleConflict      = errors.New("rule already exists")
16		ErrVersionConflict   = errors.New("rule version conflict")
17		ErrInvalidRule       = errors.New("invalid rule")
18	)
19	
20	// Rule is a per-device threshold rule. It judges only samples accepted while
21	// enabled; it never backfills history. Device and ID are immutable after
22	// creation. Version starts at 1 and bumps on every successful update.
23	type Rule struct {
24		ID        string    `json:"id"`
25		Metric    string    `json:"metric"`
26		Trigger   float64   `json:"trigger"`
27		Recover   float64   `json:"recover"`
28		Enabled   bool      `json:"enabled"`
29		Version   int64     `json:"version"`
30		CreatedAt time.Time `json:"createdAt"`
31		UpdatedAt time.Time `json:"updatedAt"`
32	}
33	
34	// Alert is one threshold crossing. It retains the rule version and the
35	// metric/thresholds in force when it fired. A natural recovery records the
36	// recovery sample's sequence, value and observed time; an end caused by a rule
37	// update records the server time and reason instead.
38	type Alert struct {
39		ID                int64      `json:"id"`
40		RuleID            string     `json:"ruleId"`
41		RuleVersion       int64      `json:"ruleVersion"`
42		Metric            string     `json:"metric"`
43		Trigger           float64    `json:"trigger"`
44		Recover           float64    `json:"recover"`
45		Status            string     `json:"status"` // "active" | "ended"
46		TriggerSequence   int64      `json:"triggerSequence"`
47		TriggerValue      float64    `json:"triggerValue"`
48		TriggerObservedAt time.Time  `json:"triggerObservedAt"`
49		RecoverSequence   *int64     `json:"recoverSequence,omitempty"`
50		RecoverValue      *float64   `json:"recoverValue,omitempty"`
51		RecoverObservedAt *time.Time `json:"recoverObservedAt,omitempty"`
52		EndedAt           *time.Time `json:"endedAt,omitempty"`
53		EndReason         string     `json:"endReason,omitempty"` // "recovered" | "rule_changed"
54		AcknowledgedAt    *time.Time `json:"acknowledgedAt,omitempty"`
55	}
56	
57	const (
58		alertStatusActive = "active"
59		alertStatusEnded  = "ended"
60		endReasonRecovered = "recovered"
61		endReasonRuleChanged = "rule_changed"
62	)
63	
64	// ruleState pairs a rule with the id of its currently active alert (0 when
65	// none).
66	type ruleState struct {
67		rule          Rule
68		activeAlertID int64
69	}
70	
71	type Device struct {
72		ID            string             `json:"id"`
73		Site          string             `json:"site"`
74		RegisteredAt  time.Time          `json:"registeredAt"`
75		LastSeenAt    time.Time          `json:"lastSeenAt"`
76		LastTelemetry map[string]float64 `json:"lastTelemetry,omitempty"`
77	}
78	
79	// Event is a single telemetry sample retained in a device's history.
80	type Event struct {
81		Sequence   int64              `json:"sequence"`
82		ObservedAt time.Time          `json:"observedAt"`
83		Values     map[string]float64 `json:"values"`
84	}
85	
86	// Sample is one replayed sample, decoded from the replay request body.
87	type Sample struct {
88		EventID    string
89		ObservedAt time.Time
90		Values     map[string]float64
91	}
92	
93	// ReplayReceipt summarises the outcome of a replay batch.
94	type ReplayReceipt struct {
95		BatchID      string         `json:"batchId"`
96		NewCount     int            `json:"newCount"`
97		Duplicate    int            `json:"duplicateCount"`
98		SampleStatus []SampleStatus `json:"samples"`
99	}
100	
101	// SampleStatus reports the history sequence assigned to (or reused by) a sample.
102	type SampleStatus struct {
103		EventID   string `json:"eventId"`
104		Sequence  int64  `json:"sequence"`
105		Duplicate bool   `json:"duplicate"`
106	}
107	
108	// HistoryFilter narrows a history query by observed-time range. Zero times mean
109	// the bound is open.
110	type HistoryFilter struct {
111		From time.Time
112		To   time.Time
113	}
114	
115	// StoredBatch records the ordered samples an accepted batchId committed along
116	// with the receipt returned on first acceptance, so a repeated batchId can be
117	// checked for identical content and replayed with the original receipt.
118	type storedBatch struct {
119		samples []Sample
120		receipt ReplayReceipt
121	}
122	
123	type deviceState struct {
124		device  Device
125		events  []Event          // history ordered by sequence (sequence = index + 1)
126		byEvent map[string]int64 // eventId -> sequence
127		batches map[string]storedBatch
128		rules   map[string]*ruleState
129		alerts  []*Alert // per-device, ordered by alert id (id = index + 1)
130	}
131	
132	type Store struct {
133		mu      sync.RWMutex
134		devices map[string]*deviceState
135		now     func() time.Time
136	
137		// wal is nil in memory mode. When set, every mutation is appended and
138		// synced here before in-memory state changes or success is returned.
139		wal walSink
140		iid []byte // data-directory instance id bound into history cursors
141	}
142	
143	func NewStore() *Store {
144		return &Store{devices: make(map[string]*deviceState), now: time.Now}
145	}
146	
147	// instanceID identifies the backing data directory; cursors are scoped to it.
148	// It is nil in memory mode.
149	func (s *Store) instanceID() []byte {
150		s.mu.RLock()
151		defer s.mu.RUnlock()
152		return s.iid
153	}
154	
155	// Exists reports whether a device is registered.
156	func (s *Store) Exists(id string) bool {
157		s.mu.RLock()
158		defer s.mu.RUnlock()
159		_, ok := s.devices[id]
160		return ok
161	}
162	
163	func (s *Store) Register(id, site string) (Device, bool, error) {
164		s.mu.Lock()
165		defer s.mu.Unlock()
166		if state, ok := s.devices[id]; ok {
167			return cloneDevice(state.device), false, nil
168		}
169		now := s.now().UTC()
170		device := Device{ID: id, Site: site, RegisteredAt: now, LastSeenAt: now}
171		if s.wal != nil {
172			if err := s.wal.appendRecord(recRegister, walRegister{
173				ID: id, Site: site, RegisteredAt: now, LastSeenAt: now,
174			}); err != nil {
175				return Device{}, false, storageUnavailable(err)
176			}
177		}
178		s.devices[id] = &deviceState{
179			device:  device,
180			byEvent: make(map[string]int64),
181			batches: make(map[string]storedBatch),
182			rules:   make(map[string]*ruleState),
183		}
184		return cloneDevice(device), true, nil
185	}
186	
187	// RecordTelemetry stores a live telemetry sample in the device history. The
188	// sample has no caller-supplied eventId, so it is never a replay duplicate; its
189	// observed time is the server receive time.
190	func (s *Store) RecordTelemetry(id string, values map[string]float64) (Device, error) {
191		s.mu.Lock()
192		defer s.mu.Unlock()
193		state, ok := s.devices[id]
194		if !ok {
195			return Device{}, ErrDeviceNotFound
196		}
197		now := s.now().UTC()
198		sequence := int64(len(state.events)) + 1
199		eval := newAlertEvaluator(state)
200		eval.evaluate(sequence, now, values)
201		if s.wal != nil {
202			if err := s.wal.appendRecord(recTelemetry, walTelemetry{
203				DeviceID:   id,
204				Sequence:   sequence,
205				ObservedAt: now,
206				Values:     values,
207				Alerts:     eval.created,
208				Ended:      eval.ended,
209			}); err != nil {
210				return Device{}, storageUnavailable(err)
211			}
212		}
213		state.events = append(state.events, Event{
214			Sequence:   sequence,
215			ObservedAt: now,
216			Values:     cloneTelemetry(values),
217		})
218		state.device.LastSeenAt = now
219		state.device.LastTelemetry = cloneTelemetry(values)
220		eval.commit()
221		return cloneDevice(state.device), nil
222	}
223	
224	// Replay validates and commits a batch atomically. repeat is true when the
225	// batchId was already committed with identical content and the first receipt
226	// is returned unchanged. It returns ErrDeviceNotFound for an unknown device and
227	// ErrBatchConflict when any sample clashes with an existing eventId or the
228	// batchId was previously committed with different ordered content; in either
229	// conflict case no state changes.
230	func (s *Store) Replay(id, batchID string, samples []Sample) (receipt ReplayReceipt, repeat bool, err error) {
231		s.mu.Lock()
232		defer s.mu.Unlock()
233		state, ok := s.devices[id]
234		if !ok {
235			return ReplayReceipt{}, false, ErrDeviceNotFound
236		}
237	
238		if previous, exists := state.batches[batchID]; exists {
239			if !sameOrderedSamples(previous.samples, samples) {
240				return ReplayReceipt{}, false, ErrBatchConflict
241			}
242			return cloneReceipt(previous.receipt), true, nil
243		}
244	
245		// Validate every sample against committed history before appending so a
246		// conflict rolls back without leaving sequences, events or receipts.
247		type plan struct {
248			sample   Sample
249			sequence int64
250			dup      bool
251		}
252		planned := make([]plan, len(samples))
253		nextSequence := int64(len(state.events)) + 1
254		for i, sample := range samples {
255			if sequence, seen := state.byEvent[sample.EventID]; seen {
256				existing := state.events[sequence-1]
257				if !sameInstant(existing.ObservedAt, sample.ObservedAt) ||
258					!sameValues(existing.Values, sample.Values) {
259					return ReplayReceipt{}, false, ErrBatchConflict
260				}
261				planned[i] = plan{sample, sequence, true}
262				continue
263			}
264			planned[i] = plan{sample, nextSequence, false}
265			nextSequence++
266		}
267	
268		// Build the receipt from the plan: only samples that matched a committed
269		// event before this batch are duplicates.
270		receipt = ReplayReceipt{BatchID: batchID, SampleStatus: make([]SampleStatus, 0, len(samples))}
271		for _, entry := range planned {
272			receipt.SampleStatus = append(receipt.SampleStatus, SampleStatus{
273				EventID:   entry.sample.EventID,
274				Sequence:  entry.sequence,
275				Duplicate: entry.dup,
276			})
277			if entry.dup {
278				receipt.Duplicate++
279			} else {
280				receipt.NewCount++
281			}
282		}
283	
284		// Evaluate the batch's new samples against the device's enabled rules, in
285		// array order (which is receive-sequence order). Duplicates never judge,
286		// create, end or refresh alerts. A trigger and a recovery inside one batch
287		// both produce alert changes, all committed together with the batch.
288		eval := newAlertEvaluator(state)
289		for _, entry := range planned {
290			if entry.dup {
291				continue
292			}
293			eval.evaluate(entry.sequence, entry.sample.ObservedAt, entry.sample.Values)
294		}
295	
296		// Durable commit point: the whole batch is one record, synced before any
297		// in-memory state changes and before success is reported. A failure here
298		// leaves sequences, history, receipts, device state and alert changes
299		// untouched.
300		lastNew := -1
301		for i, entry := range planned {
302			if !entry.dup {
303				lastNew = i
304			}
305		}
306		var committedAt time.Time
307		if s.wal != nil {
308			record := walReplay{
309				DeviceID: id,
310				BatchID:  batchID,
311				Samples:  make([]walSample, len(samples)),
312				Receipt:  receipt,
313				Alerts:   eval.created,
314				Ended:    eval.ended,
315			}
316			for i, sample := range samples {
317				record.Samples[i] = walSample{
318					EventID:    sample.EventID,
319					ObservedAt: sample.ObservedAt,
320					Values:     sample.Values,
321				}
322			}
323			if lastNew >= 0 {
324				committedAt = s.now().UTC()
325				record.LastSeenAt = &committedAt
326				record.LastTelemetry = cloneTelemetry(samples[lastNew].Values)
327			}
328			if err := s.wal.appendRecord(recReplay, record); err != nil {
329				return ReplayReceipt{}, false, storageUnavailable(err)
330			}
331		}
332	
333		// Commit: append new samples in array order.
334		for _, entry := range planned {
335			if entry.dup {
336				continue
337			}
338			state.events = append(state.events, Event{
339				Sequence:   entry.sequence,
340				ObservedAt: entry.sample.ObservedAt,
341				Values:     cloneTelemetry(entry.sample.Values),
342			})
343			state.byEvent[entry.sample.EventID] = entry.sequence
344		}
345	
346		committed := make([]Sample, len(samples))
347		copy(committed, samples)
348		for i := range committed {
349			committed[i].Values = cloneTelemetry(samples[i].Values)
350		}
351		state.batches[batchID] = storedBatch{samples: committed, receipt: cloneReceipt(receipt)}
352	
353		if lastNew >= 0 {
354			if s.wal == nil {
355				committedAt = s.now().UTC()
356			}
357			state.device.LastSeenAt = committedAt
358			state.device.LastTelemetry = cloneTelemetry(samples[lastNew].Values)
359		}
360		eval.commit()
361		return receipt, false, nil
362	}
363	
364	func cloneReceipt(receipt ReplayReceipt) ReplayReceipt {
365		receipt.SampleStatus = append([]SampleStatus(nil), receipt.SampleStatus...)
366		return receipt
367	}
368	
369	// --- rules and alerts -------------------------------------------------------
370	
371	// ruleUpdate carries the mutable fields of a rule update. A nil pointer leaves
372	// the field unchanged.
373	type ruleUpdate struct {
374		Metric  *string
375		Trigger *float64
376		Recover *float64
377		Enabled *bool
378	}
379	
380	// AlertFilter narrows an alert listing. An empty string or nil pointer leaves
381	// that dimension unfiltered.
382	type AlertFilter struct {
383		RuleID       string
384		Status       string
385		Acknowledged *bool
386	}
387	
388	// CreateRule registers a new enabled rule on a device. Version starts at 1.
389	// It returns ErrDeviceNotFound for an unknown device and ErrRuleConflict when
390	// the device already has a rule with that id.
391	func (s *Store) CreateRule(id, ruleID, metric string, trigger, recover float64) (Rule, error) {
392		s.mu.Lock()
393		defer s.mu.Unlock()
394		state, ok := s.devices[id]
395		if !ok {
396			return Rule{}, ErrDeviceNotFound
397		}
398		if _, exists := state.rules[ruleID]; exists {
399			return Rule{}, ErrRuleConflict
400		}
401		now := s.now().UTC()
402		rule := Rule{
403			ID: ruleID, Metric: metric, Trigger: trigger, Recover: recover,
404			Enabled: true, Version: 1, CreatedAt: now, UpdatedAt: now,
405		}
406		if s.wal != nil {
407			if err := s.wal.appendRecord(recRule, walRule{DeviceID: id, Rule: rule}); err != nil {
408				return Rule{}, storageUnavailable(err)
409			}
410		}
411		state.rules[ruleID] = &ruleState{rule: rule}
412		return cloneRule(rule), nil
413	}
414	
415	// UpdateRule applies a version-checked optimistic update. A version mismatch
416	// returns ErrVersionConflict with state unchanged. Every successful update
417	// bumps the version by one and immediately ends the rule's active alert (if
418	// any) with reason rule_changed; the rule starts again with no active alert.
419	func (s *Store) UpdateRule(id, ruleID string, update ruleUpdate, version int64) (Rule, []*Alert, error) {
420		s.mu.Lock()
421		defer s.mu.Unlock()
422		state, ok := s.devices[id]
423		if !ok {
424			return Rule{}, nil, ErrDeviceNotFound
425		}
426		rs, ok := state.rules[ruleID]
427		if !ok {
428			return Rule{}, nil, ErrRuleNotFound
429		}
430		if rs.rule.Version != version {
431			return Rule{}, nil, ErrVersionConflict
432		}
433	
434		updated := rs.rule
435		if update.Metric != nil {
436			updated.Metric = *update.Metric
437		}
438		if update.Trigger != nil {
439			updated.Trigger = *update.Trigger
440		}
441		if update.Recover != nil {
442			updated.Recover = *update.Recover
443		}
444		if update.Enabled != nil {
445			updated.Enabled = *update.Enabled
446		}
447		if updated.Recover >= updated.Trigger {
448			return Rule{}, nil, ErrInvalidRule
449		}
450	
451		// End the active alert of the old version before publishing the new one.
452		var ended []*Alert
453		if rs.activeAlertID != 0 {
454			alert := cloneAlert(*state.alerts[rs.activeAlertID-1])
455			alert.Status = alertStatusEnded
456			alert.EndReason = endReasonRuleChanged
457			now := s.now().UTC()
458			alert.EndedAt = &now
459			ended = append(ended, &alert)
460			rs.activeAlertID = 0
461		}
462	
463		updated.Version++
464		updated.UpdatedAt = s.now().UTC()
465	
466		if s.wal != nil {
467			if err := s.wal.appendRecord(recRule, walRule{DeviceID: id, Rule: updated, Ended: ended}); err != nil {
468				return Rule{}, nil, storageUnavailable(err)
469			}
470		}
471		rs.rule = updated
472		for _, alert := range ended {
473			state.alerts[alert.ID-1] = alert
474		}
475		return cloneRule(updated), cloneAlerts(ended), nil
476	}
477	
478	// GetRule returns one rule.
479	func (s *Store) GetRule(id, ruleID string) (Rule, error) {
480		s.mu.RLock()
481		defer s.mu.RUnlock()
482		state, ok := s.devices[id]
483		if !ok {
484			return Rule{}, ErrDeviceNotFound
485		}
486		rs, ok := state.rules[ruleID]
487		if !ok {
488			return Rule{}, ErrRuleNotFound
489		}
490		return cloneRule(rs.rule), nil
491	}
492	
493	// ListRules returns a device's rules, ordered by rule id.
494	func (s *Store) ListRules(id string) ([]Rule, error) {
495		s.mu.RLock()
496		defer s.mu.RUnlock()
497		state, ok := s.devices[id]
498		if !ok {
499			return nil, ErrDeviceNotFound
500		}
501		rules := make([]Rule, 0, len(state.rules))
502		for _, rs := range state.rules {
503			rules = append(rules, cloneRule(rs.rule))
504		}
505		sort.Slice(rules, func(i, j int) bool { return rules[i].ID < rules[j].ID })
506		return rules, nil
507	}
508	
509	// AckAlert records the server time of the first acknowledgment. Repeated
510	// acknowledgments keep the original time and write nothing. It returns
511	// ErrDeviceNotFound for an unknown device and ErrAlertNotFound for an unknown
512	// alert id.
513	func (s *Store) AckAlert(id string, alertID int64) (Alert, error) {
514		s.mu.Lock()
515		defer s.mu.Unlock()
516		state, ok := s.devices[id]
517		if !ok {
518			return Alert{}, ErrDeviceNotFound
519		}
520		if alertID < 1 || int(alertID) > len(state.alerts) {
521			return Alert{}, ErrAlertNotFound
522		}
523		alert := state.alerts[alertID-1]
524		if alert.AcknowledgedAt != nil {
525			return cloneAlert(*alert), nil
526		}
527		now := s.now().UTC()
528		if s.wal != nil {
529			if err := s.wal.appendRecord(recAlertAck, walAlertAck{
530				DeviceID: id, AlertID: alertID, AcknowledgedAt: now,
531			}); err != nil {
532				return Alert{}, storageUnavailable(err)
533			}
534		}
535		alert.AcknowledgedAt = &now
536		return cloneAlert(*alert), nil
537	}
538	
539	// ListAlerts returns a device's alerts with the given filters, ordered by
540	// alert id.
541	func (s *Store) ListAlerts(id string, filter AlertFilter) ([]Alert, error) {
542		s.mu.RLock()
543		defer s.mu.RUnlock()
544		state, ok := s.devices[id]
545		if !ok {
546			return nil, ErrDeviceNotFound
547		}
548		if filter.RuleID != "" {
549			if _, ok := state.rules[filter.RuleID]; !ok {
550				return nil, ErrRuleNotFound
551			}
552		}
553		alerts := make([]Alert, 0, len(state.alerts))
554		for _, alert := range state.alerts {
555			if filter.RuleID != "" && alert.RuleID != filter.RuleID {
556				continue
557			}
558			if filter.Status != "" && alert.Status != filter.Status {
559				continue
560			}
561			if filter.Acknowledged != nil {
562				acknowledged := alert.AcknowledgedAt != nil
563				if *filter.Acknowledged != acknowledged {
564					continue
565				}
566			}
567			alerts = append(alerts, cloneAlert(*alert))
568		}
569		return alerts, nil
570	}
571	
572	// alertEvaluator applies accepted samples to a device's enabled rules without
573	// mutating state until commit. It tracks which rule currently has an active
574	// alert so a trigger and a recovery inside the same batch are both handled in
575	// order.
576	type alertEvaluator struct {
577		state        *deviceState
578		activeByRule map[string]int64 // ruleID -> active alert id (0 when none)
579		created      []*Alert
580		ended        []*Alert
581		nextID       int64
582	}
583	
584	func newAlertEvaluator(state *deviceState) *alertEvaluator {
585		eval := &alertEvaluator{
586			state:        state,
587			activeByRule: make(map[string]int64, len(state.rules)),
588			nextID:       int64(len(state.alerts)) + 1,
589		}
590		for id, rs := range state.rules {
591			eval.activeByRule[id] = rs.activeAlertID
592		}
593		return eval
594	}
595	
596	// evaluate judges one accepted sample. A value at or above the trigger opens
597	// an alert (or keeps the existing one); a value at or below the recovery
598	// threshold ends the active alert; anything in between or a missing metric
599	// leaves state unchanged.
600	func (eval *alertEvaluator) evaluate(seq int64, observedAt time.Time, values map[string]float64) {
601		for _, rs := range eval.state.rules {
602			if !rs.rule.Enabled {
603				continue
604			}
605			value, ok := values[rs.rule.Metric]
606			if !ok {
607				continue
608			}
609			activeID := eval.activeByRule[rs.rule.ID]
610			if value >= rs.rule.Trigger && activeID == 0 {
611				alert := &Alert{
612					ID:                eval.nextID,
613					RuleID:            rs.rule.ID,
614					RuleVersion:       rs.rule.Version,
615					Metric:            rs.rule.Metric,
616					Trigger:           rs.rule.Trigger,
617					Recover:           rs.rule.Recover,
618					Status:            alertStatusActive,
619					TriggerSequence:   seq,
620					TriggerValue:      value,
621					TriggerObservedAt: observedAt,
622				}
623				eval.nextID++
624				eval.created = append(eval.created, alert)
625				eval.activeByRule[rs.rule.ID] = alert.ID
626			} else if value <= rs.rule.Recover && activeID != 0 {
627				var source *Alert
628				if activeID <= int64(len(eval.state.alerts)) {
629					source = eval.state.alerts[activeID-1]
630				} else {
631					source = eval.created[activeID-int64(len(eval.state.alerts))-1]
632				}
633				alert := cloneAlert(*source)
634				alert.Status = alertStatusEnded
635				alert.EndReason = endReasonRecovered
636				alert.RecoverSequence = &seq
637				alert.RecoverValue = &value
638				alert.RecoverObservedAt = &observedAt
639				eval.ended = append(eval.ended, &alert)
640				eval.activeByRule[rs.rule.ID] = 0
641			}
642		}
643	}
644	
645	// commit publishes the planned alert changes to the device state.
646	func (eval *alertEvaluator) commit() {
647		applyAlertChanges(eval.state, eval.created, eval.ended)
648	}
649	
650	// applyAlertChanges appends created alerts and replaces ended ones, keeping
651	// each rule's active-alert pointer in sync. It is shared by live evaluation
652	// and WAL recovery.
653	func applyAlertChanges(state *deviceState, created, ended []*Alert) {
654		for _, alert := range created {
655			state.alerts = append(state.alerts, alert)
656			if rs, ok := state.rules[alert.RuleID]; ok {
657				rs.activeAlertID = alert.ID
658			}
659		}
660		for _, alert := range ended {
661			state.alerts[alert.ID-1] = alert
662			if rs, ok := state.rules[alert.RuleID]; ok && rs.activeAlertID == alert.ID {
663				rs.activeAlertID = 0
664			}
665		}
666	}
667	
668	func cloneRule(rule Rule) Rule {
669		return rule
670	}
671	
672	func cloneAlert(alert Alert) Alert {
673		if alert.RecoverSequence != nil {
674			seq := *alert.RecoverSequence
675			alert.RecoverSequence = &seq
676		}
677		if alert.RecoverValue != nil {
678			value := *alert.RecoverValue
679			alert.RecoverValue = &value
680		}
681		if alert.RecoverObservedAt != nil {
682			t := *alert.RecoverObservedAt
683			alert.RecoverObservedAt = &t
684		}
685		if alert.EndedAt != nil {
686			t := *alert.EndedAt
687			alert.EndedAt = &t
688		}
689		if alert.AcknowledgedAt != nil {
690			t := *alert.AcknowledgedAt
691			alert.AcknowledgedAt = &t
692		}
693		return alert
694	}
695	
696	func cloneAlerts(alerts []*Alert) []*Alert {
697		if alerts == nil {
698			return nil
699		}
700		cloned := make([]*Alert, len(alerts))
701		for i, alert := range alerts {
702			c := cloneAlert(*alert)
703			cloned[i] = &c
704		}
705		return cloned
706	}
707	
708	// History returns one page of a device's event history. afterIndex is the first
709	// 0-based event slot to scan (0 for the first page); limit caps the number of
710	// matching events returned. bound pins the scan to sequences no larger than
711	// bound; a zero bound means "current maximum", which is then returned so
712	// callers can pin subsequent pages. nextIndex is the slot a following page
713	// should start at when hasMore is true. Concurrent writes therefore cannot
714	// skip or duplicate rows within a paged walk.
715	func (s *Store) History(id string, filter HistoryFilter, afterIndex, bound int64, limit int) (events []Event, appliedBound, nextIndex int64, hasMore bool, err error) {
716		s.mu.RLock()
717		defer s.mu.RUnlock()
718		state, ok := s.devices[id]
719		if !ok {
720			return nil, 0, 0, false, ErrDeviceNotFound
721		}
722		highWater := int64(len(state.events))
723		if bound == 0 {
724			bound = highWater
725		}
726		events = make([]Event, 0, limit)
727		for index := afterIndex; index < bound; index++ {
728			event := state.events[index]
729			if !filter.From.IsZero() && event.ObservedAt.Before(filter.From) {
730				continue
731			}
732			if !filter.To.IsZero() && event.ObservedAt.After(filter.To) {
733				continue
734			}
735			if len(events) < limit {
736				events = append(events, cloneEvent(event))
737				continue
738			}
739			// This match belongs to the next page; resume scanning here so rows in
740			// the gap are never examined twice.
741			return events, bound, index, true, nil
742		}
743		return events, bound, bound, false, nil
744	}
745	
746	func (s *Store) Snapshot() []Device {
747		s.mu.RLock()
748		defer s.mu.RUnlock()
749		result := make([]Device, 0, len(s.devices))
750		for _, state := range s.devices {
751			result = append(result, cloneDevice(state.device))
752		}
753		sort.Slice(result, func(i, j int) bool { return result[i].ID < result[j].ID })
754		return result
755	}
756	
757	func cloneDevice(device Device) Device {
758		device.LastTelemetry = cloneTelemetry(device.LastTelemetry)
759		return device
760	}
761	
762	func cloneEvent(event Event) Event {
763		event.Values = cloneTelemetry(event.Values)
764		return event
765	}
766	
767	func cloneTelemetry(values map[string]float64) map[string]float64 {
768		if values == nil {
769			return nil
770		}
771		cloned := make(map[string]float64, len(values))
772		for key, value := range values {
773			cloned[key] = value
774		}
775		return cloned
776	}
777	
778	// sameInstant compares times as UTC instants.
779	func sameInstant(a, b time.Time) bool {
780		return a.UTC().Equal(b.UTC())
781	}
782	
783	// sameValues compares metric maps by key and value.
784	func sameValues(a, b map[string]float64) bool {
785		if len(a) != len(b) {
786			return false
787		}
788		for key, value := range a {
789			other, ok := b[key]
790			if !ok || value != other {
791				return false
792			}
793		}
794		return true
795	}
796	
797	// sameOrderedSamples reports whether two batches carry the same samples in the
798	// same order, compared as UTC instants and key/value maps.
799	func sameOrderedSamples(a, b []Sample) bool {
800		if len(a) != len(b) {
801			return false
802		}
803		for i := range a {
804			if a[i].EventID != b[i].EventID ||
805				!sameInstant(a[i].ObservedAt, b[i].ObservedAt) ||
806				!sameValues(a[i].Values, b[i].Values) {
807				return false
808			}
809		}
810		return true
811	}
812

