97	func (h *handler) replay(w http.ResponseWriter, r *http.Request) {
98		var request replayRequest
99		if err := decodeSingleJSON(r, &request); err != nil {
100			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "request body must be a single valid JSON object"})
101			return
102		}
103		if strings.TrimSpace(request.BatchID) == "" {
104			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "batchId is required"})
105			return
106		}
107		if len(request.Samples) < 1 || len(request.Samples) > 100 {
108			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "samples must contain between 1 and 100 entries"})
109			return
110		}
111		samples := make([]Sample, len(request.Samples))
112		seenEventIDs := make(map[string]struct{}, len(request.Samples))
113		for i, entry := range request.Samples {
114			eventID := strings.TrimSpace(entry.EventID)
115			if eventID == "" {
116				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "each sample requires a non-blank eventId"})
117				return
118			}
119			if _, dup := seenEventIDs[eventID]; dup {
120				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "eventId values must be unique within a batch"})
121				return
122			}
123			seenEventIDs[eventID] = struct{}{}
124			observedAt, err := time.Parse(time.RFC3339, entry.ObservedAt)
125			if err != nil {
126				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "observedAt must be RFC3339 formatted"})
127				return
128			}
129			if len(entry.Values) == 0 || hasBlankKey(entry.Values) {
130				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "values must be a non-empty map with non-blank metric names"})
131				return
132			}
133			if !finiteValues(entry.Values) {
134				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "values must be finite numbers"})
135				return
136			}
137			samples[i] = Sample{
138				EventID:    eventID,
139				ObservedAt: observedAt.UTC(),
140				Values:     cloneTelemetry(entry.Values),
141			}
142		}
143	
144		receipt, repeat, err := h.store.Replay(r.PathValue("id"), strings.TrimSpace(request.BatchID), samples)
145		if errors.Is(err, ErrDeviceNotFound) {
146			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
147			return
148		}
149		if errors.Is(err, ErrBatchConflict) {
150			writeJSON(w, http.StatusConflict, map[string]string{"error": err.Error()})
151			return
152		}
153		if errors.Is(err, ErrStorageUnavailable) {
154			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
155			return
156		}
157		if err != nil {
158			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
159			return
160		}
161		status := http.StatusAccepted
162		if repeat {
163			status = http.StatusOK
164		}
165		writeJSON(w, status, receipt)
166	}
