168	func (h *handler) history(w http.ResponseWriter, r *http.Request) {
169		id := r.PathValue("id")
170		query := r.URL.Query()
171	
172		filter := HistoryFilter{}
173		if raw := strings.TrimSpace(query.Get("from")); raw != "" {
174			from, err := time.Parse(time.RFC3339, raw)
175			if err != nil {
176				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "from must be RFC3339 formatted"})
177				return
178			}
179			filter.From = from.UTC()
180		}
181		if raw := strings.TrimSpace(query.Get("to")); raw != "" {
182			to, err := time.Parse(time.RFC3339, raw)
183			if err != nil {
184				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "to must be RFC3339 formatted"})
185				return
186			}
187			filter.To = to.UTC()
188		}
189		if !filter.From.IsZero() && !filter.To.IsZero() && filter.From.After(filter.To) {
190			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "from must not be after to"})
191			return
192		}
193	
194		limit := 20
195		if raw := strings.TrimSpace(query.Get("limit")); raw != "" {
196			value, err := strconv.Atoi(raw)
197			if err != nil || value < 1 || value > 100 {
198				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "limit must be between 1 and 100"})
199				return
200			}
201			limit = value
202		}
203	
204		var afterIndex, highWater int64
205		rawCursor := strings.TrimSpace(query.Get("cursor"))
206		if rawCursor != "" {
207			// An unknown device is always 404, even with a malformed or foreign
208			// cursor; cursor problems on a registered device are 400.
209			if !h.store.Exists(id) {
210				writeJSON(w, http.StatusNotFound, map[string]string{"error": ErrDeviceNotFound.Error()})
211				return
212			}
213			cursor, err := decodeCursor(rawCursor)
214			if err != nil || cursor.DeviceID != id ||
215				!bytes.Equal(cursor.IID, h.store.instanceID()) ||
216				!cursor.From.Equal(filter.From) || !cursor.To.Equal(filter.To) {
217				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid cursor"})
218				return
219			}
220			afterIndex, highWater = cursor.ScanPos, cursor.HighWater
221		}
222	
223		events, appliedBound, nextIndex, hasMore, err := h.store.History(id, filter, afterIndex, highWater, limit)
224		if errors.Is(err, ErrDeviceNotFound) {
225			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
226			return
227		}
228		if err != nil {
229			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
230			return
231		}
232		highWater = appliedBound
233	
234		var nextCursor any
235		if hasMore {
236			nextCursor = encodeCursor(pageCursor{
237				DeviceID:  id,
238				From:      filter.From,
239				To:        filter.To,
240				HighWater: highWater,
241				ScanPos:   nextIndex,
242				IID:       h.store.instanceID(),
243			})
244		}
245	
246		writeJSON(w, http.StatusOK, map[string]any{
247			"deviceId":   id,
248			"events":     events,
249			"nextCursor": nextCursor,
250		})
251	}
