338	func (h *handler) updateRule(w http.ResponseWriter, r *http.Request) {
339		var request struct {
340			Metric  *string  `json:"metric"`
341			Trigger *float64 `json:"trigger"`
342			Recover *float64 `json:"recover"`
343			Enabled *bool    `json:"enabled"`
344			Version int64    `json:"version"`
345		}
346		if err := decodeJSON(r, &request); err != nil {
347			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "request body must be a single valid JSON object"})
348			return
349		}
350		if request.Version < 1 {
351			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "version is required"})
352			return
353		}
354		if request.Metric != nil && strings.TrimSpace(*request.Metric) == "" {
355			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "metric must not be blank"})
356			return
357		}
358		if request.Trigger != nil && !finiteFloat(*request.Trigger) {
359			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "trigger must be a finite number"})
360			return
361		}
362		if request.Recover != nil && !finiteFloat(*request.Recover) {
363			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "recover must be a finite number"})
364			return
365		}
366		update := ruleUpdate{}
367		if request.Metric != nil {
368			metric := strings.TrimSpace(*request.Metric)
369			update.Metric = &metric
370		}
371		if request.Trigger != nil {
372			update.Trigger = request.Trigger
373		}
374		if request.Recover != nil {
375			update.Recover = request.Recover
376		}
377		if request.Enabled != nil {
378			update.Enabled = request.Enabled
379		}
380		rule, _, err := h.store.UpdateRule(r.PathValue("id"), r.PathValue("ruleId"), update, request.Version)
381		if errors.Is(err, ErrDeviceNotFound) || errors.Is(err, ErrRuleNotFound) {
382			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
383			return
384		}
385		if errors.Is(err, ErrVersionConflict) {
386			writeJSON(w, http.StatusConflict, map[string]string{"error": err.Error()})
387			return
388		}
389		if errors.Is(err, ErrInvalidRule) {
390			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "recover threshold must be less than trigger threshold"})
391			return
392		}
393		if errors.Is(err, ErrStorageUnavailable) {
394			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
395			return
396		}
397		if err != nil {
398			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
399			return
400		}
401		writeJSON(w, http.StatusOK, rule)
402	}
403	
404	// --- alerts -----------------------------------------------------------------
405	
406	func (h *handler) listAlerts(w http.ResponseWriter, r *http.Request) {
407		query := r.URL.Query()
408		filter := AlertFilter{RuleID: strings.TrimSpace(query.Get("ruleId"))}
409		if raw := strings.TrimSpace(query.Get("status")); raw != "" {
410			if raw != alertStatusActive && raw != alertStatusEnded {
411				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "status must be active or ended"})
412				return
413			}
414			filter.Status = raw
415		}
416		if raw := strings.TrimSpace(query.Get("acknowledged")); raw != "" {
417			switch raw {
418			case "true", "1":
419				v := true
420				filter.Acknowledged = &v
421			case "false", "0":
422				v := false
423				filter.Acknowledged = &v
424			default:
425				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "acknowledged must be true or false"})
426				return
427			}
428		}
429		alerts, err := h.store.ListAlerts(r.PathValue("id"), filter)
430		if errors.Is(err, ErrDeviceNotFound) {
431			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
432			return
433		}
434		if errors.Is(err, ErrRuleNotFound) {
435			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
436			return
437		}
438		if err != nil {
439			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
440			return
441		}
442		writeJSON(w, http.StatusOK, map[string]any{"alerts": alerts})
443	}
444	
445	func (h *handler) ackAlert(w http.ResponseWriter, r *http.Request) {
446		alertID, err := strconv.ParseInt(r.PathValue("alertId"), 10, 64)
447		if err != nil || alertID < 1 {
448			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "alertId must be a positive integer"})
449			return
450		}
451		alert, err := h.store.AckAlert(r.PathValue("id"), alertID)
452		if errors.Is(err, ErrDeviceNotFound) || errors.Is(err, ErrAlertNotFound) {
453			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
454			return
455		}
456		if errors.Is(err, ErrStorageUnavailable) {
457			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
458			return
459		}
460		if err != nil {
461			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
462			return
463		}
464		writeJSON(w, http.StatusOK, alert)
465	}
466	
467	func finiteFloat(value float64) bool {
468		return !math.IsNaN(value) && !math.IsInf(value, 0)
469	}
470	
471	func hasBlankKey(values map[string]float64) bool {
472		for key := range values {
473			if strings.TrimSpace(key) == "" {
474				return true
475			}
476		}
477		return false
478	}
479	
480	func finiteValues(values map[string]float64) bool {
481		for _, value := range values {
482			if math.IsNaN(value) || math.IsInf(value, 0) {
483				return false
484			}
485		}
486		return true
487	}
488	
489	func decodeJSON(r *http.Request, target any) error {
490		decoder := json.NewDecoder(http.MaxBytesReader(nil, r.Body, 1<<20))
491		decoder.DisallowUnknownFields()
492		return decoder.Decode(target)
493	}
494	
495	// decodeSingleJSON requires the body to be exactly one JSON value, rejecting
496	// trailing data such as a second JSON object or concatenated documents.
497	func decodeSingleJSON(r *http.Request, target any) error {
498		decoder := json.NewDecoder(http.MaxBytesReader(nil, r.Body, 1<<20))
499		decoder.DisallowUnknownFields()
500		if err := decoder.Decode(target); err != nil {
501			return err
502		}
503		var trailing any
504		if err := decoder.Decode(&trailing); !errors.Is(err, io.EOF) {
505			return errors.New("body must contain a single JSON value")
506		}
507		return nil
508	}
509	
510	func writeJSON(w http.ResponseWriter, status int, value any) {
511		w.Header().Set("Content-Type", "application/json")
512		w.WriteHeader(status)
513		_ = json.NewEncoder(w).Encode(value)
514	}
