1	package fleet
2	
3	import (
4		"crypto/rand"
5		"encoding/binary"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"hash/crc32"
10		"io"
11		"io/fs"
12		"os"
13		"path/filepath"
14		"sync"
15		"syscall"
16		"time"
17	)
18	
19	// Persistent mode stores every acknowledged mutation as one checksummed record
20	// in an append-only write-ahead log. A record is the commit unit: either the
21	// whole record is durable (and visible after recovery) or none of it is, so a
22	// replay batch can never leave half of its samples behind.
23	//
24	// Commit protocol per write (WAL frame and commit journal are separate files so
25	// the commit decision never depends on parsing a possibly torn frame length):
26	//
27	//  1. write the frame at the committed offset and fsync the WAL;
28	//  2. append a fixed-size entry carrying the new committed WAL length to the
29	//     commit journal and fsync it;
30	//  3. only then report success.
31	//
32	// Recovery reads the committed length T from the journal, verifies that WAL
33	// bytes [header, T) form an exact chain of valid frames, applies them, and
34	// treats bytes (T, EOF] as the residue of an unacknowledged write. Damage to
35	// committed bytes always fails startup instead of being trimmed away.
36	
37	const (
38		walName     = "wal.log"
39		commitName  = "commit.log"
40		lockName    = "lock"
41		walMagic    = "EDGEFLET" // 8 bytes
42		headerLen   = 16         // magic(8) + version(4) + flags(4)
43		walVersion  = 1
44		commitEntry = 12 // [committed WAL length uint64 LE][crc32 LE]
45	
46		// maxRecordPayload bounds a single frame; HTTP bodies are capped at 1MiB so
47		// this only rejects absurd length fields from damaged files.
48		maxRecordPayload = 8 << 20
49	)
50	
51	const (
52		recInstance byte = 1 + iota
53		recRegister
54		recTelemetry
55		recReplay
56		recRule
57		recAlertAck
58	)
59	
60	// ErrStorageUnavailable wraps a durable-write failure at runtime. A request
61	// that fails this way never mutated queryable state.
62	var ErrStorageUnavailable = errors.New("storage unavailable")
63	
64	var crcTable = crc32.MakeTable(crc32.Castagnoli)
65	
66	// walSink is the commit log behind a persistent store.
67	type walSink interface {
68		appendRecord(recType byte, value any) error
69	}
70	
71	type walInstance struct {
72		InstanceID []byte `json:"instanceId"`
73	}
74	
75	type walRegister struct {
76		ID           string    `json:"id"`
77		Site         string    `json:"site"`
78		RegisteredAt time.Time `json:"registeredAt"`
79		LastSeenAt   time.Time `json:"lastSeenAt"`
80	}
81	
82	type walTelemetry struct {
83		DeviceID   string             `json:"deviceId"`
84		Sequence   int64              `json:"sequence"`
85		ObservedAt time.Time          `json:"observedAt"`
86		Values     map[string]float64 `json:"values"`
87		// Alerts and Ended carry the alert changes judged from this sample, in the
88		// same commit unit as the sample itself. Absent in records written before
89		// alerting existed.
90		Alerts []*Alert `json:"alerts,omitempty"`
91		Ended  []*Alert `json:"ended,omitempty"`
92	}
93	
94	type walSample struct {
95		EventID    string             `json:"eventId"`
96		ObservedAt time.Time          `json:"observedAt"`
97		Values     map[string]float64 `json:"values"`
98	}
99	
100	// walReplay is one committed batch. Samples holds the full ordered batch
101	// (duplicates included) and Receipt the first-acceptance receipt; new events
102	// and their sequences are derived by zipping the two during recovery. Alerts
103	// and Ended carry the alert changes judged from the batch's new samples, in
104	// the same commit unit as the batch itself.
105	type walReplay struct {
106		DeviceID      string             `json:"deviceId"`
107		BatchID       string             `json:"batchId"`
108		Samples       []walSample        `json:"samples"`
109		Receipt       ReplayReceipt      `json:"receipt"`
110		LastSeenAt    *time.Time         `json:"lastSeenAt,omitempty"`
111		LastTelemetry map[string]float64 `json:"lastTelemetry,omitempty"`
112		Alerts        []*Alert           `json:"alerts,omitempty"`
113		Ended         []*Alert           `json:"ended,omitempty"`
114	}
115	
116	// walRule is one committed rule create or update. Ended holds the alerts the
117	// update terminated with reason rule_changed, in the same commit unit.
118	type walRule struct {
119		DeviceID string  `json:"deviceId"`
120		Rule     Rule    `json:"rule"`
121		Ended    []*Alert `json:"ended,omitempty"`
122	}
123	
124	// walAlertAck is one committed alert acknowledgment.
125	type walAlertAck struct {
126		DeviceID       string    `json:"deviceId"`
127		AlertID        int64     `json:"alertId"`
128		AcknowledgedAt time.Time `json:"acknowledgedAt"`
129	}
130	
131	// walFile is the durable backend. walDurable is the committed WAL length (also
132	// the next frame offset); commitDurable is the journal length. Both files are
133	// truncated back to those offsets before every write, so residue left by a
134	// failed write can never be mistaken for later committed data.
135	type walFile struct {
136		walF          *os.File
137		commitF       *os.File
138		lock          *os.File
139		mu            sync.Mutex
140		walDurable    int64
141		commitDurable int64
142	}
143	
144	func (w *walFile) appendRecord(recType byte, value any) error {
145		frame, err := marshalFrame(recType, value)
146		if err != nil {
147			return err
148		}
149		w.mu.Lock()
150		defer w.mu.Unlock()
151	
152		// Remove residue any previous failed attempt may have left, then phase 1.
153		if err := w.walF.Truncate(w.walDurable); err != nil {
154			return err
155		}
156		if err := pwriteAll(w.walF, frame, w.walDurable); err != nil {
157			return err
158		}
159		if err := w.walF.Sync(); err != nil {
160			return err
161		}
162	
163		// Phase 2: publish the new committed length in the fixed-width journal.
164		newLength := w.walDurable + int64(len(frame))
165		entry := make([]byte, commitEntry)
166		binary.LittleEndian.PutUint64(entry[0:8], uint64(newLength))
167		binary.LittleEndian.PutUint32(entry[8:12], commitCRC(entry[0:8]))
168		if err := w.commitF.Truncate(w.commitDurable); err != nil {
169			return err
170		}
171		if err := pwriteAll(w.commitF, entry, w.commitDurable); err != nil {
172			return err
173		}
174		if err := w.commitF.Sync(); err != nil {
175			return err
176		}
177	
178		w.walDurable = newLength
179		w.commitDurable += int64(commitEntry)
180		return nil
181	}
182	
183	func commitCRC(sizeBytes []byte) uint32 {
184		return crc32.Checksum(sizeBytes, crcTable)
185	}
186	
187	func pwriteAll(f *os.File, buf []byte, offset int64) error {
188		for len(buf) > 0 {
189			n, err := f.WriteAt(buf, offset)
190			if err != nil {
191				return err
192			}
193			buf = buf[n:]
194			offset += int64(n)
195		}
196		return nil
197	}
198	
199	func (w *walFile) Close() error {
200		walErr := w.walF.Close()
201		commitErr := w.commitF.Close()
202		// Closing the lock fd releases the flock; a killed process releases it via
203		// the kernel, so no manual lock cleanup is ever required.
204		lockErr := w.lock.Close()
205		if walErr != nil {
206			return walErr
207		}
208		if commitErr != nil {
209			return commitErr
210		}
211		return lockErr
212	}
213	
214	// NewPersistentStore opens (or creates) a data directory and finishes full
215	// recovery before returning. It fails rather than falling back to memory when
216	// the directory cannot be created, locked, read or written, when another
217	// process already holds the directory, or when committed data is corrupt or
218	// in an unsupported format.
219	func NewPersistentStore(dir string) (_ *Store, err error) {
220		if fi, statErr := os.Stat(dir); statErr == nil {
221			if !fi.IsDir() {
222				return nil, fmt.Errorf("data path %s is not a directory", dir)
223			}
224		} else if !errors.Is(statErr, fs.ErrNotExist) {
225			return nil, fmt.Errorf("cannot access data directory %s: %w", dir, statErr)
226		}
227		if err := os.MkdirAll(dir, 0o755); err != nil {
228			return nil, fmt.Errorf("cannot create data directory %s: %w", dir, err)
229		}
230	
231		// Take the inter-process lock before reading or writing any business data.
232		lockPath := filepath.Join(dir, lockName)
233		lockFile, err := os.OpenFile(lockPath, os.O_RDWR|os.O_CREATE|syscall.O_CLOEXEC, 0o600)
234		if err != nil {
235			return nil, fmt.Errorf("cannot open lock file %s: %w", lockPath, err)
236		}
237		if lockErr := syscall.Flock(int(lockFile.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); lockErr != nil {
238			_ = lockFile.Close()
239			return nil, fmt.Errorf("data directory %s is already in use by another edge-fleet process: %w", dir, lockErr)
240		}
241		handedOff := false
242		defer func() {
243			if !handedOff {
244				_ = lockFile.Close()
245			}
246		}()
247	
248		walPath := filepath.Join(dir, walName)
249		commitPath := filepath.Join(dir, commitName)
250		walF, err := os.OpenFile(walPath, os.O_RDWR|os.O_CREATE|syscall.O_CLOEXEC, 0o600)
251		if err != nil {
252			return nil, fmt.Errorf("cannot open write-ahead log %s: %w", walPath, err)
253		}
254		commitF, err := os.OpenFile(commitPath, os.O_RDWR|os.O_CREATE|syscall.O_CLOEXEC, 0o600)
255		if err != nil {
256			_ = walF.Close()
257			return nil, fmt.Errorf("cannot open commit journal %s: %w", commitPath, err)
258		}
259		committed := false
260		defer func() {
261			if !committed {
262				_ = walF.Close()
263				_ = commitF.Close()
264			}
265		}()
266	
267		walInfo, err := walF.Stat()
268		if err != nil {
269			return nil, fmt.Errorf("cannot stat write-ahead log %s: %w", walPath, err)
270		}
271		if walInfo.Size() == 0 {
272			if _, err := walF.WriteAt(walHeader(), 0); err != nil {
273				return nil, fmt.Errorf("cannot initialise write-ahead log %s: %w", walPath, err)
274			}
275			if err := walF.Sync(); err != nil {
276				return nil, fmt.Errorf("cannot flush write-ahead log %s: %w", walPath, err)
277			}
278		}
279	
280		walData, err := io.ReadAll(walF)
281		if err != nil {
282			return nil, fmt.Errorf("cannot read write-ahead log %s: %w", walPath, err)
283		}
284		commitData, err := io.ReadAll(commitF)
285		if err != nil {
286			return nil, fmt.Errorf("cannot read commit journal %s: %w", commitPath, err)
287		}
288		if len(walData) < headerLen || string(walData[0:8]) != walMagic {
289			return nil, fmt.Errorf("write-ahead log %s is corrupt: bad magic header", walPath)
290		}
291		version := binary.LittleEndian.Uint32(walData[8:12])
292		if version != walVersion {
293			return nil, fmt.Errorf("write-ahead log %s uses unsupported format version %d (this server supports %d)", walPath, version, walVersion)
294		}
295		if binary.LittleEndian.Uint32(walData[12:16]) != 0 {
296			return nil, fmt.Errorf("write-ahead log %s is corrupt: bad header flags", walPath)
297		}
298	
299		// Recover the committed WAL length from the fixed-width journal. A short
300		// final block is a torn append from a write that never reported success;
301		// a full block with a bad CRC is committed-data damage. Entries must chain
302		// strictly forward and never point past the WAL. For a fresh journal the
303		// committed prefix is the header itself.
304		walDurable, commitDurable := int64(headerLen), int64(0)
305		for pos := 0; pos < len(commitData); pos += commitEntry {
306			if len(commitData)-pos < commitEntry {
307				break // torn tail: discarded by the truncate below
308			}
309			block := commitData[pos : pos+commitEntry]
310			declared := int64(binary.LittleEndian.Uint64(block[0:8]))
311			if binary.LittleEndian.Uint32(block[8:12]) != commitCRC(block[0:8]) {
312				return nil, fmt.Errorf("commit journal %s is corrupt at byte %d: bad checksum (files left untouched)", commitPath, pos)
313			}
314			if declared <= walDurable || declared > int64(len(walData)) || declared < headerLen {
315				return nil, fmt.Errorf("commit journal %s is corrupt at byte %d: committed length %d is inconsistent", commitPath, pos, declared)
316			}
317			walDurable = declared
318			commitDurable = int64(pos + commitEntry)
319		}
320	
321		// Every byte the journal claims committed must form an exact chain of
322		// valid, in-range frames. Failure here is damage to acknowledged data.
323		type parsedFrame struct {
324			recType byte
325			payload []byte
326		}
327		frames := make([]parsedFrame, 0)
328		pos := headerLen
329		for int64(pos) < walDurable {
330			if pos+5 > len(walData) {
331				return nil, fmt.Errorf("write-ahead log %s is corrupt at byte %d: truncated frame inside committed prefix", walPath, pos)
332			}
333			length := int(binary.LittleEndian.Uint32(walData[pos : pos+4]))
334			frameLen := 5 + length + 4
335			if length > maxRecordPayload || int64(pos+frameLen) > walDurable {
336				return nil, fmt.Errorf("write-ahead log %s is corrupt at byte %d: frame length %d is invalid within the committed prefix", walPath, pos, length)
337			}
338			recType := walData[pos+4]
339			payload := walData[pos+5 : pos+5+length]
340			wantCRC := binary.LittleEndian.Uint32(walData[pos+5+length : pos+frameLen])
341			if crc32.Checksum(walData[pos:pos+5+length], crcTable) != wantCRC {
342				return nil, fmt.Errorf("write-ahead log %s is corrupt at byte %d: frame failed its integrity check (file left untouched)", walPath, pos)
343			}
344			if recType < recInstance || recType > recAlertAck {
345				return nil, fmt.Errorf("write-ahead log %s uses unsupported record type %d at byte %d", walPath, recType, pos)
346			}
347			frames = append(frames, parsedFrame{recType: recType, payload: payload})
348			pos += frameLen
349		}
350		if int64(pos) != walDurable {
351			return nil, fmt.Errorf("write-ahead log %s is corrupt: committed length %d is not a frame boundary", walPath, walDurable)
352		}
353	
354		// Rebuild relational state from the committed frames, in order.
355		store := NewStore()
356		var instanceID []byte
357		sawInstance := false
358		for i, frame := range frames {
359			switch frame.recType {
360			case recInstance:
361				if sawInstance || i != 0 {
362					return nil, fmt.Errorf("write-ahead log %s is corrupt: instance marker out of place", walPath)
363				}
364				var rec walInstance
365				if err := json.Unmarshal(frame.payload, &rec); err != nil || len(rec.InstanceID) == 0 || len(rec.InstanceID) > 64 {
366					return nil, fmt.Errorf("write-ahead log %s is corrupt: invalid instance marker: %w", walPath, err)
367				}
368				instanceID = rec.InstanceID
369				sawInstance = true
370			case recRegister, recTelemetry, recReplay, recRule, recAlertAck:
371				if !sawInstance {
372					return nil, fmt.Errorf("write-ahead log %s is corrupt: data record precedes instance marker", walPath)
373				}
374				if err := applyRecord(store, frame.recType, frame.payload); err != nil {
375					return nil, fmt.Errorf("write-ahead log %s is corrupt: %w", walPath, err)
376				}
377			}
378		}
379	
380		// Discard unacknowledged residue: bytes from a request that never reached
381		// its journal entry (crash mid-write or a request that returned 503).
382		if int64(len(walData)) != walDurable {
383			if err := walF.Truncate(walDurable); err != nil {
384				return nil, fmt.Errorf("cannot discard unacknowledged tail of %s: %w", walPath, err)
385			}
386			if err := walF.Sync(); err != nil {
387				return nil, fmt.Errorf("cannot flush truncated %s: %w", walPath, err)
388			}
389		}
390		if int64(len(commitData)) != commitDurable {
391			if err := commitF.Truncate(commitDurable); err != nil {
392				return nil, fmt.Errorf("cannot discard torn entry of %s: %w", commitPath, err)
393			}
394			if err := commitF.Sync(); err != nil {
395				return nil, fmt.Errorf("cannot flush truncated %s: %w", commitPath, err)
396			}
397		}
398	
399		wal := &walFile{
400			walF:          walF,
401			commitF:       commitF,
402			lock:          lockFile,
403			walDurable:    walDurable,
404			commitDurable: commitDurable,
405		}
406		if !sawInstance {
407			instanceID = newInstanceID()
408			if err := wal.appendRecord(recInstance, walInstance{InstanceID: instanceID}); err != nil {
409				return nil, fmt.Errorf("cannot write instance marker to %s: %w", walPath, err)
410			}
411		}
412		// Make freshly created directory entries durable as well.
413		if dirFile, err := os.Open(dir); err != nil {
414			return nil, fmt.Errorf("cannot open data directory %s for sync: %w", dir, err)
415		} else {
416			syncErr := syscall.Fsync(int(dirFile.Fd()))
417			_ = dirFile.Close()
418			if syncErr != nil {
419				return nil, fmt.Errorf("cannot flush data directory %s: %w", dir, syncErr)
420			}
421		}
422	
423		store.wal = wal
424		store.iid = instanceID
425		committed = true
426		handedOff = true
427		return store, nil
428	}
429	
430	// Close releases the WAL files and the directory lock.
431	func (s *Store) Close() error {
432		if closer, ok := s.wal.(interface{ Close() error }); ok {
433			return closer.Close()
434		}
435		return nil
436	}
437	
438	func storageUnavailable(err error) error {
439		return fmt.Errorf("%w: %v", ErrStorageUnavailable, err)
440	}
441	
442	func walHeader() []byte {
443		header := make([]byte, headerLen)
444		copy(header[0:8], walMagic)
445		binary.LittleEndian.PutUint32(header[8:12], walVersion)
446		return header
447	}
448	
449	// marshalFrame frames one record as
450	// [length uint32 LE][type byte][payload][crc32 LE].
451	// The CRC covers length, type and payload, so even a damaged length field of
452	// the final frame fails verification instead of masquerading as a torn tail.
453	func marshalFrame(recType byte, value any) ([]byte, error) {
454		payload, err := json.Marshal(value)
455		if err != nil {
456			return nil, err
457		}
458		if len(payload) > maxRecordPayload {
459			return nil, fmt.Errorf("wal record too large: %d bytes", len(payload))
460		}
461		frame := make([]byte, 5+len(payload)+4)
462		binary.LittleEndian.PutUint32(frame[0:4], uint32(len(payload)))
463		frame[4] = recType
464		copy(frame[5:], payload)
465		binary.LittleEndian.PutUint32(frame[5+len(payload):], crc32.Checksum(frame[:5+len(payload)], crcTable))
466		return frame, nil
467	}
468	
469	// applyAlertRecord validates and applies the alert changes carried by a
470	// telemetry or replay record. It rejects relational inconsistency so a damaged
471	// WAL fails startup rather than producing broken alert state.
472	func applyAlertRecord(state *deviceState, created, ended []*Alert) error {
473		wantID := int64(len(state.alerts)) + 1
474		for _, alert := range created {
475			if alert == nil {
476				return errors.New("alert record contains a null create")
477			}
478			if alert.ID != wantID {
479				return fmt.Errorf("alert create id mismatch: got %d, want %d", alert.ID, wantID)
480			}
481			if alert.Status != alertStatusActive || alert.RuleID == "" || alert.Metric == "" ||
482				alert.TriggerSequence <= 0 || alert.TriggerObservedAt.IsZero() {
483				return fmt.Errorf("alert %d create is incomplete", alert.ID)
484			}
485			wantID++
486		}
487		maxID := int64(len(state.alerts) + len(created))
488		for _, alert := range ended {
489			if alert == nil {
490				return errors.New("alert record contains a null end")
491			}
492			if alert.ID < 1 || alert.ID > maxID {
493				return fmt.Errorf("alert end id %d out of range (1..%d)", alert.ID, maxID)
494			}
495			if alert.Status != alertStatusEnded || alert.EndReason != endReasonRecovered {
496				return fmt.Errorf("alert %d end is malformed", alert.ID)
497			}
498		}
499		applyAlertChanges(state, created, ended)
500		return nil
501	}
502	
503	// applyRecord rebuilds in-memory state from one committed record, rejecting
504	// any structural or relational inconsistency. It never calls the clock, so
505	// recovery cannot refresh device timestamps.
506	func applyRecord(s *Store, recType byte, payload []byte) error {
507		switch recType {
508		case recRegister:
509			var rec walRegister
510			if err := json.Unmarshal(payload, &rec); err != nil {
511				return fmt.Errorf("invalid register record: %w", err)
512			}
513			if rec.ID == "" || rec.RegisteredAt.IsZero() || rec.LastSeenAt.IsZero() {
514				return errors.New("register record missing fields")
515			}
516			if _, exists := s.devices[rec.ID]; exists {
517				return fmt.Errorf("duplicate registration for device %q", rec.ID)
518			}
519			s.devices[rec.ID] = &deviceState{
520				device: Device{
521					ID:           rec.ID,
522					Site:         rec.Site,
523					RegisteredAt: rec.RegisteredAt.UTC(),
524					LastSeenAt:   rec.LastSeenAt.UTC(),
525				},
526				byEvent: make(map[string]int64),
527				batches: make(map[string]storedBatch),
528				rules:   make(map[string]*ruleState),
529			}
530			return nil
531	
532		case recTelemetry:
533			var rec walTelemetry
534			if err := json.Unmarshal(payload, &rec); err != nil {
535				return fmt.Errorf("invalid telemetry record: %w", err)
536			}
537			state, ok := s.devices[rec.DeviceID]
538			if !ok {
539				return fmt.Errorf("telemetry for unknown device %q", rec.DeviceID)
540			}
541			if rec.Sequence != int64(len(state.events))+1 {
542				return fmt.Errorf("device %q telemetry sequence gap: got %d, want %d", rec.DeviceID, rec.Sequence, len(state.events)+1)
543			}
544			if rec.ObservedAt.IsZero() || len(rec.Values) == 0 {
545				return fmt.Errorf("device %q telemetry record missing fields", rec.DeviceID)
546			}
547			state.events = append(state.events, Event{
548				Sequence:   rec.Sequence,
549				ObservedAt: rec.ObservedAt.UTC(),
550				Values:     cloneTelemetry(rec.Values),
551			})
552			state.device.LastSeenAt = rec.ObservedAt.UTC()
553			state.device.LastTelemetry = cloneTelemetry(rec.Values)
554			if err := applyAlertRecord(state, rec.Alerts, rec.Ended); err != nil {
555				return err
556			}
557			return nil
558	
559		case recReplay:
560			var rec walReplay
561			if err := json.Unmarshal(payload, &rec); err != nil {
562				return fmt.Errorf("invalid replay record: %w", err)
563			}
564			state, ok := s.devices[rec.DeviceID]
565			if !ok {
566				return fmt.Errorf("replay for unknown device %q", rec.DeviceID)
567			}
568			if rec.BatchID == "" || len(rec.Samples) == 0 || len(rec.Samples) != len(rec.Receipt.SampleStatus) {
569				return fmt.Errorf("device %q replay record is incomplete", rec.DeviceID)
570			}
571			if rec.Receipt.BatchID != rec.BatchID {
572				return fmt.Errorf("device %q receipt batchId %q does not match %q", rec.DeviceID, rec.Receipt.BatchID, rec.BatchID)
573			}
574			if _, exists := state.batches[rec.BatchID]; exists {
575				return fmt.Errorf("device %q duplicate stored receipt for batch %q", rec.DeviceID, rec.BatchID)
576			}
577	
578			samples := make([]Sample, len(rec.Samples))
579			newCount, dupCount := 0, 0
580			lastNew := -1
581			for i, entry := range rec.Samples {
582				status := rec.Receipt.SampleStatus[i]
583				if entry.EventID == "" || entry.ObservedAt.IsZero() || len(entry.Values) == 0 {
584					return fmt.Errorf("device %q batch %q sample %d is incomplete", rec.DeviceID, rec.BatchID, i)
585				}
586				if status.EventID != entry.EventID {
587					return fmt.Errorf("device %q batch %q receipt/sample eventId mismatch at %d", rec.DeviceID, rec.BatchID, i)
588				}
589				samples[i] = Sample{
590					EventID:    entry.EventID,
591					ObservedAt: entry.ObservedAt.UTC(),
592					Values:     cloneTelemetry(entry.Values),
593				}
594				if sequence, seen := state.byEvent[entry.EventID]; seen {
595					existing := state.events[sequence-1]
596					if !sameInstant(existing.ObservedAt, entry.ObservedAt) || !sameValues(existing.Values, entry.Values) {
597						return fmt.Errorf("device %q dedupe record for %q disagrees with history", rec.DeviceID, entry.EventID)
598					}
599					if !status.Duplicate || status.Sequence != sequence {
600						return fmt.Errorf("device %q receipt for %q should reuse sequence %d", rec.DeviceID, entry.EventID, sequence)
601					}
602					dupCount++
603					continue
604				}
605				if status.Duplicate {
606					return fmt.Errorf("device %q receipt marks unseen event %q as duplicate", rec.DeviceID, entry.EventID)
607				}
608				want := int64(len(state.events)) + 1
609				if status.Sequence != want {
610					return fmt.Errorf("device %q batch %q sequence mismatch for %q: got %d, want %d", rec.DeviceID, rec.BatchID, entry.EventID, status.Sequence, want)
611				}
612				state.events = append(state.events, Event{
613					Sequence:   status.Sequence,
614					ObservedAt: entry.ObservedAt.UTC(),
615					Values:     cloneTelemetry(entry.Values),
616				})
617				state.byEvent[entry.EventID] = status.Sequence
618				newCount++
619				lastNew = i
620			}
621			if rec.Receipt.NewCount != newCount || rec.Receipt.Duplicate != dupCount {
622				return fmt.Errorf("device %q batch %q receipt counts disagree with samples (%d/%d vs %d/%d)",
623					rec.DeviceID, rec.BatchID, rec.Receipt.NewCount, rec.Receipt.Duplicate, newCount, dupCount)
624			}
625	
626			if newCount > 0 {
627				if rec.LastSeenAt == nil || rec.LastSeenAt.IsZero() {
628					return fmt.Errorf("device %q batch %q missing recorded receive time", rec.DeviceID, rec.BatchID)
629				}
630				if !sameValues(rec.LastTelemetry, samples[lastNew].Values) {
631					return fmt.Errorf("device %q batch %q last telemetry disagrees with last new sample", rec.DeviceID, rec.BatchID)
632				}
633				state.device.LastSeenAt = rec.LastSeenAt.UTC()
634				state.device.LastTelemetry = cloneTelemetry(rec.LastTelemetry)
635			} else if rec.LastSeenAt != nil || len(rec.LastTelemetry) != 0 {
636				return fmt.Errorf("device %q all-duplicate batch %q unexpectedly refreshed device state", rec.DeviceID, rec.BatchID)
637			}
638	
639			state.batches[rec.BatchID] = storedBatch{samples: samples, receipt: cloneReceipt(rec.Receipt)}
640			if err := applyAlertRecord(state, rec.Alerts, rec.Ended); err != nil {
641				return err
642			}
643			return nil
644	
645		case recRule:
646			var rec walRule
647			if err := json.Unmarshal(payload, &rec); err != nil {
648				return fmt.Errorf("invalid rule record: %w", err)
649			}
650			state, ok := s.devices[rec.DeviceID]
651			if !ok {
652				return fmt.Errorf("rule for unknown device %q", rec.DeviceID)
653			}
654			if rec.Rule.ID == "" || rec.Rule.Metric == "" || rec.Rule.Version < 1 ||
655				rec.Rule.CreatedAt.IsZero() || rec.Rule.UpdatedAt.IsZero() {
656				return fmt.Errorf("device %q rule record is incomplete", rec.DeviceID)
657			}
658			if existing, exists := state.rules[rec.Rule.ID]; exists {
659				if existing.rule.Version != rec.Rule.Version-1 {
660					return fmt.Errorf("device %q rule %q version gap: got %d, want %d",
661						rec.DeviceID, rec.Rule.ID, rec.Rule.Version, existing.rule.Version+1)
662				}
663				existing.rule = rec.Rule
664			} else {
665				if rec.Rule.Version != 1 {
666					return fmt.Errorf("device %q rule %q first record has version %d, want 1",
667						rec.DeviceID, rec.Rule.ID, rec.Rule.Version)
668				}
669				state.rules[rec.Rule.ID] = &ruleState{rule: rec.Rule}
670			}
671			for _, alert := range rec.Ended {
672				if alert == nil || alert.ID < 1 || int(alert.ID) > len(state.alerts) {
673					return fmt.Errorf("device %q rule %q ends unknown alert", rec.DeviceID, rec.Rule.ID)
674				}
675				if alert.Status != alertStatusEnded || alert.EndReason != endReasonRuleChanged || alert.EndedAt == nil {
676					return fmt.Errorf("device %q rule %q end of alert %d is malformed", rec.DeviceID, rec.Rule.ID, alert.ID)
677				}
678				state.alerts[alert.ID-1] = alert
679				if rs, ok := state.rules[alert.RuleID]; ok && rs.activeAlertID == alert.ID {
680					rs.activeAlertID = 0
681				}
682			}
683			return nil
684	
685		case recAlertAck:
686			var rec walAlertAck
687			if err := json.Unmarshal(payload, &rec); err != nil {
688				return fmt.Errorf("invalid alert ack record: %w", err)
689			}
690			state, ok := s.devices[rec.DeviceID]
691			if !ok {
692				return fmt.Errorf("alert ack for unknown device %q", rec.DeviceID)
693			}
694			if rec.AlertID < 1 || int(rec.AlertID) > len(state.alerts) {
695				return fmt.Errorf("device %q ack for unknown alert %d", rec.DeviceID, rec.AlertID)
696			}
697			if rec.AcknowledgedAt.IsZero() {
698				return fmt.Errorf("device %q ack for alert %d missing time", rec.DeviceID, rec.AlertID)
699			}
700			alert := state.alerts[rec.AlertID-1]
701			if alert.AcknowledgedAt == nil {
702				t := rec.AcknowledgedAt.UTC()
703				alert.AcknowledgedAt = &t
704			}
705			return nil
706	
707		default:
708			return fmt.Errorf("unknown record type %d", recType)
709		}
710	}
711	
712	func newInstanceID() []byte {
713		id := make([]byte, 16)
714		if _, err := rand.Read(id); err != nil {
715			panic(fmt.Sprintf("cannot generate instance id: %v", err))
716		}
717		return id
718	}
