			return false
		}
		for i := range av {
			if !jsonValueEqual(av[i], bv[i]) {
				return false
			}
		}
		return true
	case float64:
		// Both sides decode through encoding/json, so every JSON number is a
		// float64; == is the numeric value comparison.
		bv, ok := b.(float64)
